/* Lecture 2 — Kotlin Language Fundamentals (v2.1 upgrade, no slide limit).
   Rule: every technical word a student sees is either explained on the slide or is a [[tooltip]].
   Every program output on these slides was produced by the real Kotlin 2.2.21 compiler (see TEACHER_CHANGELOG.md).
   [[Term]] = tooltip. Definitions live in `terms` below and are also added to the course glossary. */
(function(){
const SUM='fun main() {\n    val prices = listOf(100, 200, 300)\n    var total = 0\n    for (price in prices) {\n        total += price\n    }\n    println("Total price: $total")\n}';
const BANK='class BankAccount(initial: Double) {\n    var balance = initial\n        private set                  // only the class can change it\n    fun deposit(amount: Double) {\n        if (amount > 0) balance += amount\n    }\n    fun withdraw(amount: Double): Boolean {\n        if (amount <= balance) {\n            balance -= amount\n            return true\n        }\n        println("Rejected: only $balance available")\n        return false\n    }\n}\nfun main() {\n    val acc = BankAccount(1000.0)\n    acc.deposit(500.0)\n    acc.withdraw(200.0)\n    acc.withdraw(5000.0)\n    println("Balance: ${acc.balance}")\n}';
const gradeCode=m=>'fun main() {\n    val marks = '+m+'\n    val grade = if (marks >= 90) "A"\n        else if (marks >= 80) "B"\n        else "C"\n    println("Grade: $grade")\n}';
const gradeSteps=m=>{const g=m>=90?'A':m>=80?'B':'C',s=[{l:1,n:'The program starts at `main()`.'},{l:2,v:{marks:m},n:'`marks` now holds **'+m+'**.'},
 {l:3,n:'Is '+m+' >= 90? **'+(m>=90)+'**'+(m>=90?'. So the whole `if` gives back "A".':'. Skip "A", try the next check.'),v:m>=90?{grade:'"A"'}:{}}];
 if(m<90)s.push({l:4,n:'Is '+m+' >= 80? **'+(m>=80)+'**'+(m>=80?'. So the whole `if` gives back "B".':'. Skip "B".'),v:m>=80?{grade:'"B"'}:{}});
 if(m<80)s.push({l:5,n:'No check was true, so `else` gives back "C".',v:{grade:'"C"'}});
 s.push({l:6,o:'Grade: '+g,n:'The string template puts the grade into the text.'},{l:7,n:'`main()` ends. The program is finished.'});return s};

MAD.deck(2,{
rev:'2.1',
title:'Kotlin Language Fundamentals',
subtitle:'Where Android came from, then the Kotlin you need for every app: values, types, null safety, decisions, loops, functions, collections and classes — one small idea at a time.',
intro:'Say: Today has two parts. First a short story: how Android was born and which versions matter to us. Then Kotlin itself, one small idea per slide, with live animations.\nTip for you: any word with a dotted underline is explained — hover it on the laptop or tap it on a phone.\nAsk the class: who has written code in C++ or Java before? Kotlin will feel familiar but safer.\nShort on time: keep the history to 3 minutes.',
objectives:['Explain how Android grew from 2003 to today and what minSdk / targetSdk / compileSdk mean','Write a Kotlin program with main(), println() and string templates','Store data with val and var and pick the right data type','Use null safety (?, ?., ?:, let) and avoid !!','Use operators, make decisions with if and when, and repeat work with loops and ranges','Write functions and lambdas, and use List, MutableList, Set, Map and Array','Build classes with constructors, private set, data classes, inheritance and companion objects','Connect Kotlin to an Android screen (XML layout + ViewBinding)'],
bloom:{head:['Recall the main Android versions, their API levels and one change each','Explain val vs var, nullable types, lambdas and inheritance in plain words','Trace if, when and loops line by line and predict the output'],heart:['Value null-safe, readable code over “clever” code','Stay patient with compiler errors: they are help, not punishment'],hand:['Write and run Kotlin programs in Android Studio','Build a class with private set and a data class, then use them from a button click']},
terms:{
/* history */
'API level':'A whole number that names each Android version for developers (Android 16 = API 36). Why: code can easily check “is this phone new enough?”. Like a class number at school — easier to compare than names.',
'SDK':'Software Development Kit: the ready-made tools, code libraries and documents you need to build apps for a platform. Why: you do not write everything from zero. Like the toolbox that comes with a new car.',
'Open Handset Alliance':'A group of phone makers, chip makers, mobile networks and Google, formed in 2007 to build Android together. Why: one open system that many brands can use.',
'Android Market':'The first Android app store (2008). In 2012 it became **Google Play**.',
'JIT':'Just-In-Time compiler: turns app code into fast machine code while the app is running. Why: apps run faster. Like a translator who translates each sentence the moment you speak it.',
'Dalvik':'The old Android “virtual machine” (a program that runs app code), used until Android 4.4. Why: one app file could run on many different phone chips. Replaced by ART.',
'ART':'Android Runtime: runs app code since Android 5.0 and translates it for the phone’s chip ahead of time. Why: faster start and smoother apps than Dalvik.',
'NFC':'Near Field Communication: very short-range wireless (a few cm). Used for tap-to-pay and reading smart tags.',
'Fragment':'A reusable part of a screen with its own layout and code. Several fragments can sit side by side on a tablet. Like rooms built from the same flat-pack furniture.',
'Holo':'The design style of Android 4.x: dark backgrounds with bright blue lines. Replaced by Material Design.',
'Material Design':'Google’s design language (cards, shadows, motion), introduced in Android 5.0. Why: apps look and behave in a familiar, consistent way.',
'runtime permission':'A permission the app must ASK the user for while it is running (camera, location…), since Android 6.0. Why: the user decides, not the installer. Like knocking before entering a room.',
'Doze':'A battery-saving mode (Android 6.0+): when the phone lies still with the screen off, apps’ background work is paused and done in short batches.',
'multi-window':'Showing two apps on the screen at the same time (split screen), since Android 7.0.',
'notification channel':'A category of notifications (e.g. “Messages”, “Offers”) that the user can switch on or off separately, since Android 8.0. Like separate mailboxes.',
'gesture navigation':'Moving around the phone by swiping (e.g. swipe up for home) instead of pressing three buttons at the bottom.',
'dark theme':'A system-wide dark colour scheme (Android 10+). Apps should look right in both light and dark.',
'scoped storage':'Since Android 10, each app gets its own storage area and cannot freely read all files on the phone. Why: privacy.',
'Material You':'Android 12’s design update: the phone takes colours from your wallpaper and apps can use them.',
'SplashScreen API':'The standard way (Android 12+) to show an app’s logo screen while it starts. Every app gets one automatically.',
'notification permission':'Since Android 13 an app must ask “Allow notifications?” (permission POST_NOTIFICATIONS) before it can show any notification.',
'photo picker':'A system screen (Android 13+) where the user picks photos to share with an app, so the app never needs access to the whole gallery.',
'foreground service':'Background work the user is aware of, shown by a notification (music playing, navigation). Since Android 14 it must say its type, e.g. mediaPlayback.',
'edge-to-edge':'The app draws under the status bar and navigation bar, using the whole screen. Enforced for apps that target Android 15.',
'minSdk':'The OLDEST Android version (API level) your app can be installed on. Lower = more phones, but fewer new features.',
'targetSdk':'The NEWEST Android version whose rules you have tested your app against. Android then applies that version’s behaviour to your app.',
'compileSdk':'The Android version whose SDK you build with, so you can use its newest features. Usually the latest.',
'Gradle':'The build tool Android Studio uses. It reads your build files, downloads libraries and turns your code into an app. Like a factory manager following a recipe.',
'build.gradle.kts':'The build settings file of an app module (written in Kotlin). It holds the SDK versions, the app id and the libraries the app uses.',
/* tools and first program */
'Android Studio':'Google’s official program (IDE) for building Android apps. It works offline once installed. We use it all semester.',
'IDE':'Integrated Development Environment: one program with a code editor, a run button, error highlighting and a debugger. Android Studio is an IDE.',
'Kotlin Playground':'A website (play.kotlinlang.org) that runs small Kotlin programs in the browser. Needs internet; handy for quick tests.',
'compiler':'The program that checks your code for mistakes and translates it so the computer or phone can run it. It catches many errors before the app runs.',
'console':'The text output area where `println` writes. In Android Studio it is the Run window (and Logcat for apps).',
'function':'A named block of code you can run (call) again and again. Why: write once, reuse. Like a recipe card.',
'main()':'The function where a Kotlin program starts. Why: the computer needs one clear front door.',
'println':'Prints a value in the console and then moves to a new line. `print` does the same without the new line.',
'comment':'Text the compiler ignores, written for humans: `// one line` or `/* many lines */`.',
'string template':'Putting a value inside text with `$name` or `${expression}`. Why: no messy `+` joining.',
/* variables and types */
'variable':'A named box in memory that holds a value. Why: you can use and change data by its name.',
'val':'A read-only variable: set once, cannot be re-assigned. Like a sealed lunchbox.',
'var':'A changeable variable: can be re-assigned. Like a reusable water bottle.',
'type inference':'Kotlin works out the type from the value, so `val age = 20` is an Int without writing `: Int`. Why: less typing, still safe.',
'data type':'The kind of value a variable holds (Int, Double, String…). It decides what you can do with it: you can divide numbers but not names.',
'Int':'A whole number from about −2.1 billion to +2.1 billion: 20, −5, 0.',
'Long':'A whole number that can be much bigger than an Int. Written with L at the end: `9_000_000_000L`.',
'Double':'A number with a decimal point: 99.99, 2.5. The usual choice for decimals.',
'Float':'A decimal number with less precision than Double, written with f: `2.5f`. Mostly used in graphics.',
'Boolean':'Only two values: true or false. Every comparison gives a Boolean.',
'Char':'Exactly one character in single quotes: `\'A\'`.',
'String':'Text in double quotes: `"Ayesha"`.',
'toInt()':'Turns text like "42" into the number 42. Crashes if the text is not a number; `toIntOrNull()` gives null instead.',
/* null safety */
'null':'“No value at all”. Not zero, not empty text — nothing.',
'NullPointerException':'The crash that happens when code uses something that is null as if it had a value. The most common crash in Java apps.',
'nullable type':'A type with `?` (like `String?`) that is allowed to hold null. A plain `String` can never be null.',
'safe call':'`?.` — call only if the value is not null; otherwise the result is null. No crash.',
'Elvis operator':'`?:` — “use the left value, or this default if it is null”. Named after Elvis Presley’s hairstyle `?:`.',
'let':'`x?.let { … }` runs the block only when x is not null; inside the block the value is called `it`.',
/* operators, decisions, loops */
'operator':'A symbol that does something with values: `+` adds, `>` compares, `&&` joins conditions.',
'remainder':'What is left over after dividing: `7 % 2` = 1. Handy to test even/odd (`n % 2 == 0`).',
'expression':'Code that produces a value, like `2 + 3` or `if (a > b) a else b`.',
'when':'Kotlin’s multi-way choice (a better `switch`). It can match values, ranges and types and can give back a value.',
'Any':'The parent type of every non-null Kotlin value. A parameter of type `Any` accepts an Int, a String, anything.',
'smart cast':'After `is String` is true, Kotlin automatically treats the value as a String inside that branch, so you can use `.length` without converting.',
'loop':'Code that repeats: `for`, `while`, `do-while`.',
'range':'A row of numbers like `1..5`, `1 until 5`, `5 downTo 1`, `1..10 step 2`.',
/* functions, lambdas, collections */
'parameter':'A named input in a function definition: `a` in `fun add(a: Int)`. The value you pass in a call is the argument.',
'argument':'The real value you pass when you call a function: `3` in `add(3, 4)`.',
'return type':'The type of value a function gives back, written after `):`.',
'Unit':'Kotlin’s “nothing useful to return” type (like void in Java). You may leave it out.',
'default argument':'A parameter with a ready value (`course: String = "MAD"`). The caller may skip it.',
'named argument':'Writing the parameter name in the call (`greet(name = "Sana")`) so the order does not matter and the call is easy to read.',
'lambda':'A small function without a name, written in `{ }`: `{ m: Int -> m >= 50 }`. Why: you can pass behaviour as a value, e.g. to `filter` or to a button click.',
'it':'Inside a lambda with exactly one input, `it` is the automatic name of that input.',
'function type':'The type of a lambda, e.g. `(Int) -> Boolean` = “takes an Int, gives back a Boolean”.',
'List':'An ordered, read-only collection: `listOf(...)`. You cannot add or remove items.',
'MutableList':'A list you can change: `mutableListOf(...)` with `add` and `remove`.',
'Set':'A collection with no duplicates: `setOf(3, 1, 3)` keeps 3 and 1 only once.',
'Map':'Key → value pairs: `mapOf("Ali" to 85)`. Like a dictionary: word → meaning.',
'Array':'A fixed-size row of items: `arrayOf(...)`. The size never changes, but items can be replaced.',
'index':'The position of an item, counting from 0. The first item is `[0]`.',
'joinToString':'Joins all items into one text, separated by commas: `arrayOf(1, 2).joinToString()` → "1, 2".',
/* classes */
'class':'A blueprint that describes data (properties) and actions (functions). Like a house plan.',
'object':'A real thing built from a class, with its own data. Like an actual house built from the plan. (Also a Kotlin keyword — see object declaration.)',
'property':'A variable that belongs to a class or object, like `name` in Student. Also called a data member.',
'member function':'A function that belongs to a class and works with its data, like `introduce()`. Also called a method.',
'constructor':'The code that builds a new object and sets its first values.',
'primary constructor':'The constructor written in the class header: `class Student(val name: String)`. The usual Kotlin way.',
'secondary constructor':'An extra constructor written inside the class with the `constructor` keyword. Kotlin rarely needs it.',
'init block':'`init { }` runs automatically every time an object is created.',
'this':'Inside a class, `this` means “the current object”. `this.name = name` copies the parameter into the property.',
'overloading':'Having two functions or constructors with the same name but different parameters.',
'encapsulation':'Hiding an object’s data so only its own functions can change it. Why: nobody can break the rules (e.g. make a negative balance).',
'private set':'The property can be READ from anywhere but only CHANGED inside its own class.',
'data class':'`data class` = a class for holding data; Kotlin writes toString, equals and copy for you.',
'toString':'Turns an object into readable text. A data class prints like `Student(name=Ali, marks=85)`.',
'copy':'Makes a new data-class object with some values changed: `a.copy(marks = 90)`.',
'inheritance':'A child class gets all the properties and functions of a parent class and can add its own. Why: reuse code instead of copying it.',
'open':'Kotlin classes and functions are closed by default. `open` allows a child class to inherit or override them.',
'override':'A child class replaces a parent’s function with its own version.',
'polymorphism':'The same call does different things depending on the real object: `sound()` gives “Woof” for a Dog and “Meow” for a Cat.',
'object declaration':'`object Name { }` creates exactly ONE object (a singleton) — e.g. app settings.',
'companion object':'Things inside a class that belong to the class itself, not to each object — like a shared counter. Called with the class name: `Student.count`.',
/* Android bridge */
'XML layout':'A file (res/layout/*.xml) that describes what a screen looks like: buttons, text and their positions.',
'View':'Anything you see on an Android screen: a Button, a TextView, an image…',
'LinearLayout':'A container that places its children one after another, in a column (vertical) or a row (horizontal).',
'match_parent':'Make this view as big as its parent (container).',
'wrap_content':'Make this view just big enough for its content.',
'dp':'Density-independent pixels: a size unit that looks the same on small and large screens. Use dp for sizes and spacing.',
'sp':'Like dp but also follows the user’s font-size setting. Use sp for text sizes.',
'padding':'Empty space INSIDE a view, between its border and its content.',
'TextView':'A view that shows text.',
'Button':'A view the user taps to make something happen.',
'android:id':'A name for a view, written `@+id/btnSave`. The `+` creates the id. Kotlin uses it to find the view.',
'Activity':'One screen of an Android app with its Kotlin code (Lecture 5). Like one room in a building.',
'AppCompatActivity':'The standard Activity class to extend. It makes new Android features work on older phones too.',
'onCreate':'The function Android calls when the screen is first created. You set up the screen here.',
'Bundle':'A small bag of saved values. `savedInstanceState` holds the screen’s old state (e.g. after rotation), or null the first time.',
'ViewBinding':'Android Studio generates a class (e.g. ActivityMainBinding) with a typed field for every view that has an id. Why: safer and shorter than findViewById.',
'inflate':'Turn an XML layout into real view objects in memory. `layoutInflater` is the tool that does it.',
'setContentView':'Tells the Activity which views to show on the screen.',
'findViewById':'The older way to find a view by its id: `findViewById<Button>(R.id.btnSave)`. It crashes if the id or the type is wrong.',
'Intent':'A message used to open another screen or app and carry data to it (Lecture 5). Like a letter to another room.',
'getStringExtra':'Reads a text value that another screen put into the Intent. It returns `String?` because the value may be missing.',
'setOnClickListener':'Gives a view a lambda to run every time the user taps it.',
'lateinit':'“I will give this var a value later, before using it.” Used for things created in onCreate.',
/* today */
'K2 compiler':'The new, faster Kotlin compiler used since Kotlin 2.0. Your code stays the same; it just builds faster.',
'coroutine':'Kotlin’s light-weight way to run slow work (internet, database) without freezing the screen. Taught in Lecture 15.'
},
slides:[
/* ===== A. Android history ===== */
{tag:'Android history · 2003–2013',title:'How Android was born',text:'Android started as a small company, was bought by Google, and grew one version at a time. Each version has a number, a dessert name and an [[API level]].',
 viz:{type:'timeline',label:'Android history 2003 to 2013',speed:2600,events:[
  {y:'2003',name:'Android Inc. is founded',short:'Android Inc.',what:'A small start-up in Palo Alto (USA) starts building software for phones. Andy Rubin is a co-founder.',dev:'No apps yet. The idea: one open system that many phone makers can use.'},
  {y:'2005',name:'Google buys Android',short:'Google buys it',what:'Google buys the start-up in July 2005 and keeps building the system in secret.',dev:'Android will come with Google’s services: Maps, Gmail and later the Play Store.'},
  {y:'2007',name:'Open Handset Alliance',short:'Alliance + SDK',what:'On 5 Nov 2007 Google, phone makers, chip makers and mobile networks form the [[Open Handset Alliance]] and show Android. The first [[SDK]] preview appears.',dev:'Developers can write apps before any Android phone is on sale.'},
  {y:'2008',name:'Android 1.0',short:'1.0',api:'1',what:'The first Android phone, the HTC Dream (T-Mobile G1), is announced on 23 Sep 2008. The [[Android Market]] app store opens.',dev:'Apps can now be published and installed by the public.'},
  {y:'2009',name:'Android 1.5 Cupcake',short:'Cupcake',api:'3',code:'The first dessert name.',what:'A keyboard on the screen and home-screen widgets.',dev:'Apps can offer widgets; phones no longer need a physical keyboard.'},
  {y:'2009',name:'Android 1.6 Donut',short:'Donut',api:'4',what:'Support for different screen sizes and a quick search box.',dev:'Layouts must fit many screen sizes — still true today (Lecture 4).'},
  {y:'2009–10',name:'Android 2.0–2.1 Eclair',short:'Eclair',api:'5–7',what:'Google Maps turn-by-turn navigation, several accounts on one phone, moving (live) wallpapers.',dev:'Apps can sync data with more than one account.'},
  {y:'2010',name:'Android 2.2 Froyo',short:'Froyo',api:'8',what:'Faster apps thanks to a [[JIT]] compiler inside [[Dalvik]], Wi-Fi hotspot, apps can be installed on the SD card.',dev:'The same app code suddenly runs faster.'},
  {y:'2010',name:'Android 2.3 Gingerbread',short:'Gingerbread',api:'9–10',what:'[[NFC]] support, a better keyboard and copy-paste, a simpler look.',dev:'Apps can read NFC tags.'},
  {y:'2011',name:'Android 3.x Honeycomb',short:'Honeycomb',api:'11–13',what:'A version made only for tablets, with a top action bar and [[Fragment|Fragments]].',dev:'Fragments arrive: reusable parts of a screen for big displays.'},
  {y:'2011',name:'Android 4.0 Ice Cream Sandwich',short:'Ice Cream Sandwich',api:'14–15',what:'One system for phones AND tablets, with the new [[Holo]] design.',dev:'One app can now serve phones and tablets.'},
  {y:'2012–13',name:'Android 4.1–4.3 Jelly Bean',short:'Jelly Bean',api:'16–18',what:'“Project Butter” makes scrolling and animation smooth; notifications can expand to show more.',dev:'Smooth screens become the rule: never block the main thread (Lecture 15).'},
  {y:'2013',name:'Android 4.4 KitKat',short:'KitKat',api:'19',what:'“Project Svelte”: Android runs well on cheap phones with only 512 MB of memory (RAM). [[ART]] appears as a test option.',dev:'Apps must be careful with memory on low-cost phones.'}]},
 takeaway:'Every version = a number (API level) + a name + new rules for developers.',
 notes:'Say: Android began in 2003 as a small company. Google bought it in 2005, showed it to the world in 2007 and the first phone came in 2008. Press Play and let the timeline run; stop on Honeycomb and Ice Cream Sandwich (tablets, then one system for all).\nFun fact: the versions were named in alphabetical order — Cupcake, Donut, Eclair, Froyo…\nStudents may ask: “Why desserts?” — Google never gave an official reason; the team just liked treats and the alphabet game.\nWatch for: students mixing up version number (4.4) and API level (19). They are different numbers.\nShort on time: keep. Tap only 2008, Cupcake and KitKat.'},
{tag:'Android history · 2014–today',title:'Modern Android: each version adds new rules',text:'From 2014 almost every version changed how we must write apps. Tap a dot to see what changed for developers.',
 viz:{type:'timeline',label:'Android history 2014 to today',speed:2600,events:[
  {y:'2014',name:'Android 5.0–5.1 Lollipop',short:'Lollipop',api:'21–22',what:'[[Material Design]] arrives, and [[ART]] replaces [[Dalvik]].',dev:'App code is translated for the phone’s chip in advance: faster start, smoother running.'},
  {y:'2015',name:'Android 6.0 Marshmallow',short:'Marshmallow',api:'23',what:'[[runtime permission|Runtime permissions]], and [[Doze]] mode to save battery when the phone sleeps.',dev:'Apps must now ASK for camera, location etc. while running (Lecture 6).'},
  {y:'2016',name:'Android 7.0–7.1 Nougat',short:'Nougat',api:'24–25',what:'[[multi-window|Multi-window]]: two apps on the screen side by side.',dev:'Your screen must cope with being made smaller or bigger.'},
  {y:'2017',name:'Android 8.0–8.1 Oreo',short:'Oreo',api:'26–27',what:'[[notification channel|Notification channels]] and limits on work done in the background.',dev:'Every notification needs a channel (Lecture 7); background services are restricted (Lecture 16).'},
  {y:'2018',name:'Android 9 Pie',short:'Pie',api:'28',what:'[[gesture navigation|Gesture navigation]] begins (a “pill” instead of three buttons). The last public dessert name.',dev:'Do not put important buttons where users swipe.'},
  {y:'2019',name:'Android 10',short:'10',api:'29',code:'Public dessert names stop. Internal name: Quince Tart.',what:'System-wide [[dark theme]], full gesture navigation, [[scoped storage]].',dev:'Apps get their own storage area instead of reading every file (Lecture 8).'},
  {y:'2020',name:'Android 11',short:'11',api:'30',code:'Internal name: Red Velvet Cake.',what:'One-time permissions: the user can choose “Only this time”.',dev:'A permission may disappear later — always check before using it.'},
  {y:'2021–22',name:'Android 12 and 12L',short:'12',api:'31–32',code:'Internal name: Snow Cone.',what:'[[Material You]] (colours from the wallpaper) and the [[SplashScreen API]].',dev:'Every app gets a standard splash screen (Lecture 9).'},
  {y:'2022',name:'Android 13',short:'13',api:'33',code:'Internal name: Tiramisu.',what:'The [[notification permission]] and the [[photo picker]].',dev:'Ask before showing notifications; pick photos without full gallery access.'},
  {y:'2023',name:'Android 14',short:'14',api:'34',code:'Internal name: Upside Down Cake.',what:'Every [[foreground service]] must declare its type (for example mediaPlayback).',dev:'Lecture 16 shows the type in the manifest.'},
  {y:'2024',name:'Android 15',short:'15',api:'35',code:'Internal name: Vanilla Ice Cream.',what:'[[edge-to-edge|Edge-to-edge]] screens are enforced for apps that target Android 15.',dev:'Your layout draws behind the status bar; leave room for it.'},
  {y:'2025',name:'Android 16',short:'16',api:'36',code:'Internal name: Baklava.',what:'On large screens (600 [[dp]] wide or more), apps that target 16 can no longer lock the screen direction or size.',dev:'Layouts must work in portrait, landscape and on tablets.'},
  {y:'2026',name:'Android 17',short:'17',api:'37',code:'Newest release (June 2026).',what:'“Adaptive-first” apps, app memory limits and stricter rules for audio playing in the background.',dev:'Keep apps light and make them fit every screen size.'}]},
 takeaway:'New versions = new rules. Your app says which rules it follows with targetSdk (next slide).',
 notes:'Say: These versions matter because each one changed a rule for developers. Marshmallow: ask for permissions while running. Oreo: notification channels. Android 13: ask before notifying. Tap only those, then 17.\nFun fact: Android 10 dropped dessert names in public because a letter like “Q” has few desserts and names do not translate well; desserts are still used inside Google.\nStudents may ask: “Which version does my phone have?” — Settings → About phone → Android version.\nWatch for: thinking old phones get new versions automatically. Many never get updates — that is why minSdk matters.\nShort on time: keep; tap Marshmallow, Oreo, 13 and 17 only.'},
{kind:'code',tag:'Which versions matter to YOU',title:'minSdk, targetSdk and compileSdk',text:'Every app chooses three Android versions in its [[Gradle]] build file, [[build.gradle.kts]]. Android Studio fills them in for you when you create a project.',
 analogy:'A school: **minSdk** is the lowest class allowed in, **targetSdk** is the syllabus you prepared for, **compileSdk** is the newest textbook on your desk.',
 lang:'gradle',file:'app/build.gradle.kts',run:'none',
 code:'android {\n    compileSdk = 36\n\n    defaultConfig {\n        minSdk = 24        // Android 7.0 and newer can install\n        targetSdk = 36     // tested with Android 16 rules\n    }\n}',
 lines:[[2,'**[[compileSdk]]** = 36: build with the Android 16 SDK, so all its features are available.'],[5,'**[[minSdk]]** = 24: phones older than Android 7.0 cannot install the app. Lower = more phones.'],[6,'**[[targetSdk]]** = 36: Android applies Android 16’s rules to this app. Google Play requires a recent targetSdk.']],
 takeaway:'Low minSdk = more phones. targetSdk and compileSdk = the newest.',
 notes:'Say: Explain with the school analogy. When you create a project, Android Studio’s wizard shows what share of devices each minSdk reaches. This course uses minSdk 24.\nStudents may ask: “Why not set minSdk = 36 to get all new features?” — then most phones in Pakistan could not install the app.\nWatch for: confusing targetSdk with minSdk. Target = the rules you follow; min = the oldest phone allowed.\nShort on time: keep; read only the three lines.'},
/* ===== B + C. running code and the first program ===== */
{title:'How a Kotlin program runs',text:'You write code, the **[[compiler]]** checks and translates it, then the computer runs it and prints results in the **[[console]]**.',
 points:['Write Kotlin in **[[Android Studio]]**, our [[IDE]] (works offline; used all semester)','Or test small programs in **[[Kotlin Playground]]** (a website — needs internet)','In Android Studio: right-click a package → New → Kotlin Class/File → **File**, type `fun main()`, press the green ▶'],
 analogy:'Like writing a letter in Urdu for an English reader: the compiler is the translator who also points out spelling mistakes before sending.',
 viz:{type:'flow',nodes:[['✍️','Write','Main.kt — your Kotlin code'],['🔍','Compile','The compiler checks for mistakes and translates'],['▶️','Run','The computer follows the steps'],['🖥️','Output','println shows text in the console']],caps:['You type the program in a **.kt** file.','The **compiler** checks it. If there is a mistake it stops and shows a red error — nothing runs.','No errors? The program runs from `main()`, line by line.','Each `println` writes one line in the **console**.']},
 takeaway:'No compile errors → it runs. A red error is the compiler helping you, not punishing you.',
 notes:'Say: Show Android Studio on the projector: create a Kotlin file, type fun main, click the green triangle in the gutter, and point at the Run window (the console).\nStudents may ask: “Can I use my phone to write Kotlin?” — Kotlin Playground works in a phone browser when you have internet.\nWatch for: students saving the file with .txt — it must be .kt.\nShort on time: show the flow once, skip the IDE demo.'},
{kind:'code',title:'Your first Kotlin program',text:'Every program starts at **[[main()]]**. [[println]] prints a line; a [[string template]] puts values inside text.',
 code:'// My first Kotlin program\nfun main() {\n    val name = "Ayesha"              // a value we can reuse\n    val marks = listOf(78, 85, 92)   // three numbers in a list\n    println("Hello, Kotlin!")\n    println("Student: $name")\n    println("Total = ${marks.sum()}") /* an expression inside ${ } */\n}',
 lines:[[1,'A [[comment]]: `//` starts a note for humans. The [[compiler]] ignores it.'],[2,'`fun main()` is the front door: the program starts here. `fun` means “[[function]]”. The `{ }` braces hold its steps.'],[3,'`val name` stores the text "Ayesha" so we can use it by name (more on `val` soon).'],[4,'`listOf(...)` keeps three numbers together (lists come later).'],[5,'[[println]] prints a line in the console. Text goes inside double quotes.'],[6,'`$name` is a [[string template]]: Kotlin puts the value inside the text.'],[7,'`${...}` calculates first: marks.sum() = 78 + 85 + 92 = 255. `/* */` is a comment that can cover many lines.']],
 output:'Hello, Kotlin!\nStudent: Ayesha\nTotal = 255',change:'Change "Ayesha" to your own name and add a fourth mark. What is the new total?',
 notes:'Say: Step through the lines with S. Run it live in Android Studio.\nStudents may ask: “Why ${ } and not just $?” — $name works for a single name; anything with a dot or brackets needs ${ }.\nWatch for: missing quotes around text, and single quotes (they are only for one Char).\nShort on time: keep.'},
/* ===== D + E. variables and types ===== */
{title:'Variables: val vs var',text:'A **[[variable]]** is a named box that holds a value. **[[val]]** is set once. **[[var]]** can change. Use `val` unless the value must change.',
 analogy:'val = a sealed lunchbox: packed once, never re-packed. var = a reusable water bottle: refill it any time.',
 viz:{type:'variable',name:'score',dtype:'Int',values:[10,15,20]},
 points:['`var score = 10` then `score = 15` ✓ allowed','`val name = "Ali"` then `name = "Sara"` ✗ error: *\'val\' cannot be reassigned*'],
 takeaway:'Name + type + value = variable. Prefer val.',
 notes:'Say: Press Play: the box gets 10, then 15, then 20 — that is a var. Then show that a val would refuse the change.\nThe error message on the slide is the real one from the Kotlin compiler.\nStudents may ask: “Why ever use val if var can do everything?” — val protects you from changing something by accident; the compiler tells you immediately.\nWatch for: students declaring everything with var.\nShort on time: keep.'},
{title:'Data types: what kind of value?',text:'The **[[data type]]** tells Kotlin what kind of value a variable holds and what you can do with it.',
 viz:{type:'cards',cols:2,items:[{icon:'🔢',title:'Int',text:'Whole numbers',code:'val age: Int = 20'},{icon:'📏',title:'Long',text:'Very big whole numbers (L at the end)',code:'val stars: Long = 9_000_000_000L'},{icon:'🧮',title:'Double',text:'Decimals (the usual choice)',code:'val price: Double = 99.99'},{icon:'🎈',title:'Float',text:'Decimals, less precise (f at the end)',code:'val weight: Float = 2.5f'},{icon:'🔘',title:'Boolean',text:'Only true or false',code:'val passed: Boolean = true'},{icon:'🅰️',title:'Char',text:'One character, single quotes',code:'val grade: Char = \'A\''},{icon:'🔤',title:'String',text:'Text, double quotes',code:'val name: String = "Ayesha"'}]},
 takeaway:'Numbers without a point → Int. With a point → Double. Text → String. Yes/no → Boolean.',
 notes:'Say: Step through the cards. Underscores in 9_000_000_000 only make big numbers readable; Kotlin ignores them.\nVerified: a program declaring all seven values prints “20 9000000000 99.99 2.5 true A Ayesha”.\nStudents may ask: “Why not always use Long or Double?” — they use more memory; Int and Double are the normal choices.\nWatch for: \'A\' (Char) vs "A" (String).\nShort on time: show Int, Double, String, Boolean only.'},
{kind:'code',title:'Type inference, conversion and the division trap',text:'You may skip the type: Kotlin guesses it from the value — **[[type inference]]**. To change a type you convert it yourself, e.g. with [[toInt()]].',
 code:'fun main() {\n    val name = "Ali"            // inferred: String\n    var age = 20                // inferred: Int\n    age = 21                    // OK: var can change\n    val price: Double = 99.99   // explicit type\n    val half = 5 / 2            // Int / Int\n    val exact = 5 / 2.0         // Int / Double\n    val typed = "42".toInt() + 8\n    val cart = mutableListOf("Pen")\n    cart.add("Book")            // val list, contents still change\n    println("$name is $age years old")\n    println("$price $half $exact $typed")\n    println(cart)\n}',
 lines:[[2,'No type written; Kotlin infers **String** from the quotes.'],[3,'`var` → we may change it. Inferred **Int**.'],[4,'Re-assigning a var is fine.'],[5,'You can also write the type yourself: `: Double`.'],[6,'**Trap!** Int ÷ Int drops the decimal part: 5 / 2 = **2** (not rounded — cut off).'],[7,'If one side is a [[Double]] the result is a Double: **2.5**.'],[8,'Text → number with [[toInt()]]: "42" becomes 42, and 42 + 8 = 50.'],['9-10','`val` means the NAME cannot point to another list. The list itself (a [[MutableList]]) can still grow.'],['11-13','Print the results.']],
 output:'Ali is 21 years old\n99.99 2 2.5 50\n[Pen, Book]',
 change:'Change `5 / 2.0` back to `5 / 2`. What prints now?',
 notes:'Say: The 5 / 2 trap breaks averages and percentages in student apps every semester.\nStudents may ask: “If val cannot change, how did cart.add work?” — val locks the label, not the box’s contents. The list is mutable; the name still points to the same list.\nWatch for: text from an input box is always a String — you must convert it before maths.\nShort on time: keep lines 6–8.'},
/* ===== F. null safety ===== */
{kind:'code',tag:'Null safety · 1 of 2',title:'Why null crashes apps',text:'**[[null]]** means “no value at all”. Using a null as if it had a value causes a **[[NullPointerException]]** — the most common crash in Java apps. Kotlin stops this before the app runs.',
 analogy:'An empty box still exists (`""`). Null is **no box at all** — you cannot open what is not there.',
 code:'fun main() {\n    var name: String? = "Ali"   // String? = may be null\n    val a: String = null        // ✗ error\n    println(name.length)        // ✗ error\n}',
 lines:[[2,'Adding `?` makes a **[[nullable type]]**: `String?` may hold text OR null.'],[3,'A plain `String` can never be null. The compiler says: *null cannot be a value of a non-null type \'String\'*.'],[4,'`.length` = number of letters. But `name` might be null, so Kotlin refuses: *only safe (?.) or non-null asserted (!!.) calls are allowed on a nullable receiver of type \'String?\'*.']],
 output:'This program does not compile.\nThe two ✗ lines are the real compiler errors (Kotlin 2.2).',run:'none',
 takeaway:'`String` = always has a value. `String?` = might be null, so Kotlin makes you handle it.',
 notes:'Say: In Android, data often comes from outside — a text box, the internet, another screen — and may be missing. Kotlin forces us to think “what if it is missing?” before the app runs.\nStudents may ask: “Is an empty string null?” — No. "" is a box with nothing inside; null is no box.\nWatch for: students adding !! everywhere just to silence the compiler. Next slide shows the safe tools.\nShort on time: show only the error lines.'},
{tag:'Null safety · 2 of 2',title:'Four tools for nullable values',text:'Switch the value between **"Ali"** and **null** and step through each line.',
 points:['`?.` **[[safe call]]** — null in, null out, no crash','`?:` **[[Elvis operator]]** — give a default value','`?.let { }` — **[[let]]** runs the block only when not null','`!!` — “I promise it is not null”. A wrong promise = crash. Avoid.'],
 viz:{type:'nullsafe',value:'Ali'},
 takeaway:'Use `?.`, `?:` and `let`. Treat `!!` as a red warning light.',
 notes:'Say: Step through all five rows with "Ali", then press the null button and step again. Watch which rows change.\nVerified with the Kotlin compiler: with "Ali" → 3, Ali, Hello, Ali; with null → null, Guest, nothing printed, and !! throws java.lang.NullPointerException.\nStudents may ask: “When is !! OK?” — almost never in this course. An if-check is safer.\nWatch for: `name?.length ?: 0` — the combination they will use most.\nShort on time: keep.'},
/* ===== G. operators and if ===== */
{kind:'code',title:'Operators: maths, comparing and combining',text:'An **[[operator]]** is a symbol that works on values. Comparisons give a [[Boolean]] (true/false); `&&`, `||` and `!` combine them.',
 code:'fun main() {\n    val a = 7\n    val b = 2\n    println(a + b)              // add\n    println(a - b)              // subtract\n    println(a * b)              // multiply\n    println(a / b)              // divide (Int: decimal part dropped)\n    println(a % b)              // remainder\n    println(a > b)              // compare\n    println(a == 7 && b == 3)   // AND: both must be true\n    println(a == 7 || b == 3)   // OR: one is enough\n    println(!(a > b))           // NOT: flips true/false\n    var score = 10\n    score += 5                  // same as score = score + 5\n    score++                     // add 1\n    println(score)\n}',
 lines:[['4-6','`+` `-` `*` work as in maths: 9, 5, 14.'],[7,'Int ÷ Int = **3** (the .5 is dropped).'],[8,'`%` gives the [[remainder]]: 7 ÷ 2 = 3 remainder **1**.'],[9,'Compare with `>` `<` `>=` `<=`, equal `==`, not equal `!=`. Result: **true**.'],[10,'`&&` (AND): 7 == 7 is true but 2 == 3 is false → **false**.'],[11,'`||` (OR): one true side is enough → **true**.'],[12,'`!` (NOT) flips true to **false**.'],['13-16','`+=` adds to the current value; `++` adds 1. 10 + 5 + 1 = **16**.']],
 output:'9\n5\n14\n3\n1\ntrue\nfalse\ntrue\nfalse\n16',
 change:'Change b to 3. Which lines change?',
 notes:'Say: Read each line and let students say the answer before you step to it.\nStudents may ask: “Why == and not =?” — one = puts a value into a variable; two == asks “are they equal?”.\nWatch for: `=` inside an if — Kotlin gives an error, which is good.\nShort on time: lines 7, 8, 10, 11 only.'},
{title:'Decisions: if, else if, else',text:'`if` checks a condition. If it is true one block runs; `else if` tries the next check; `else` catches the rest. In Kotlin `if` is an **[[expression]]**: it gives back a value.',
 analogy:'A traffic warden: is it green? go. Else, is it yellow? slow down. Else stop. Only ONE action happens.',
 viz:{type:'tracer',speed:1900,input:{label:'marks',min:0,max:100,value:85},codeFor:gradeCode,gen:gradeSteps},
 takeaway:'The first true condition wins; the rest are skipped. No `? :` operator needed — `if` returns a value.',
 notes:'Say: Drag the marks slider to 95, 85 and 60 and press Play each time. Ask students to predict the grade first.\nAll cases were compiled and run (0, 60, 80, 85, 90, 95, 100): e.g. 95 → Grade: A, 85 → Grade: B, 60 → Grade: C.\nStudents may ask: “Why is there no ternary (a ? b : c) like in Java?” — because `if` already returns a value.\nWatch for: putting `marks >= 80` before `marks >= 90` — then nobody ever gets an A.\nShort on time: keep, run only 85.'},
/* ===== H. when ===== */
{kind:'code',title:'when: many choices, cleanly',text:'**[[when]]** replaces long if-else chains. It can match exact values, a [[range]] with `in`, a type with `is`, or work with no value in brackets at all.',
 code:'fun describe(x: Any): String = when (x) {\n    is Int -> "Int: $x"\n    is String -> "Text of length ${x.length}"\n    else -> "Something else"\n}\n\nfun main() {\n    val day = 6\n    val dayName = when (day) {\n        1 -> "Monday"\n        in 2..5 -> "Weekday"\n        6, 7 -> "Weekend"\n        else -> "Invalid day"\n    }\n    println(dayName)\n    println(describe(42))\n    println(describe("Kotlin"))\n    val num = 15\n    when {\n        num % 3 == 0 && num % 5 == 0 -> println("FizzBuzz")\n        num % 3 == 0 -> println("Fizz")\n        else -> println(num)\n    }\n}',
 lines:[[1,'`x: [[Any]]` accepts any value. `= when` means the function gives back whatever `when` chooses.'],['2-3','`is` checks the type. Inside that branch Kotlin already treats x as that type — a [[smart cast]] — so `x.length` works.'],[10,'Exact value: `->` means “then give”.'],[11,'`in 2..5` matches any value from 2 to 5.'],[12,'Two values in one branch, separated by a comma.'],[13,'`else` catches everything else (needed when `when` gives back a value).'],['19-23','`when` with **no value in brackets**: each branch is its own true/false check. `%` is the [[remainder]]: 15 % 3 = 0, so 15 can be divided by 3.']],
 output:'Weekend\nInt: 42\nText of length 6\nFizzBuzz',change:'Set day = 3 and num = 9. Predict both lines first.',
 notes:'Say: when is like a row of labelled doors; Kotlin walks along and opens the FIRST door whose label matches.\nStudents may ask: “Do I need break like in Java switch?” — No. Only one branch runs.\nWatch for: forgetting else when `when` is used as a value — the compiler complains.\nShort on time: skip the describe() part (lines 1-5).'},
/* ===== I. loops ===== */
{kind:'code',title:'while, do-while, break and continue',text:'A **[[loop]]** repeats a block. `while` checks first, then runs. `do-while` runs first, then checks — so it always runs at least once.',
 code:'fun main() {\n    var i = 1\n    while (i <= 3) {\n        println("while: $i")\n        i++\n    }\n    var tries = 0\n    do {\n        tries++\n        println("do-while ran $tries time")\n    } while (tries < 1)\n    for (n in 1..10) {\n        if (n == 3) continue      // skip 3\n        if (n == 6) break         // stop at 6\n        print("$n ")\n    }\n    println()\n}',
 lines:[['2-6','Repeat while i <= 3. `i++` adds 1 each round. Without it the loop would never stop (an endless loop).'],['7-11','`do { } while` runs the body first; then 1 < 1 is false, so it stops after **one** round.'],[12,'`for (n in 1..10)` gives n the values 1, 2, … 10 (more on the next slides).'],[13,'`continue` skips the rest of this round and jumps to the next value.'],[14,'`break` leaves the loop completely.'],[15,'`print` (without ln) stays on the same line.']],
 output:'while: 1\nwhile: 2\nwhile: 3\ndo-while ran 1 time\n1 2 4 5',
 change:'Remove the `continue` line. What prints now?',
 notes:'Say: Your original slide showed “1, 2, 3” on one line — println actually prints each number on its own line, as shown here.\nStudents may ask: “When do I use while instead of for?” — when you do not know in advance how many rounds, e.g. “keep asking until the password is right”.\nWatch for: forgetting i++ → the program never ends. In Android Studio press the red ■ stop button.\nShort on time: skip do-while.'},
{title:'for loop: watch it step by step',text:'`for (price in prices)` visits every item of a list once. Watch the variables change line by line.',
 viz:{type:'tracer',speed:1500,code:SUM,steps:[
  {l:1,n:'The program starts at `main()`.'},{l:2,v:{prices:'[100, 200, 300]'},n:'A list with three prices.'},{l:3,v:{total:0},n:'`total` starts at 0. It is a `var` because it will change.'},
  {l:4,v:{price:100},n:'The loop takes the first item: price = 100.'},{l:5,v:{total:100},n:'total = 0 + 100 = 100.'},
  {l:4,v:{price:200},n:'Next item: price = 200.'},{l:5,v:{total:300},n:'total = 100 + 200 = 300.'},
  {l:4,v:{price:300},n:'Last item: price = 300.'},{l:5,v:{total:600},n:'total = 300 + 300 = 600.'},
  {l:4,v:{price:null},n:'No items left, so the loop ends. `price` only exists inside the loop.'},
  {l:7,o:'Total price: 600',n:'Print the result with a string template.'},{l:8,n:'`main()` ends.'}]},
 takeaway:'Use `for` for “each item”. Verified output: Total price: 600.',
 notes:'Say: Press Play. Point at the green flash in the Variables box every time total changes. The loop line (4) is visited 4 times: 3 items + 1 check that finds nothing left.\nStudents may ask: “Why is total a var but prices a val?” — total changes; the list does not.\nWatch for: off-by-one errors with <= vs <.\nShort on time: keep.'},
{title:'Ranges explorer',text:'A [[range]] is a row of numbers a `for` loop can walk through. Change start, kind, end and step, then press Step to see each value of `i`.',
 points:['`1..10` includes 10 · `1 until 10` stops at 9','`10 downTo 1` counts backwards · `step 2` jumps by 2'],
 viz:{type:'range',a:1,b:10,kind:'..',step:2,speed:900},
 takeaway:'`..` includes the end, `until` excludes it. A range like `5..1` is empty: the loop never runs.',
 notes:'Say: Try these and ask students to predict before pressing Play: 1..10 step 2 → 1 3 5 7 9; 1 until 5 → 1 2 3 4; 10 downTo 1 step 2 → 10 8 6 4 2; 10 downTo 1 step 3 → 10 7 4 1; 5..1 → nothing. All verified with the Kotlin compiler.\nStudents may ask: “Can step be negative?” — No, step must be positive. Use downTo to go backwards.\nWatch for: expecting 5..1 to count down. It is empty.\nShort on time: show two ranges only.'},
/* ===== J. functions ===== */
{title:'Functions: little machines',text:'A **[[function]]** is a named machine: you give it inputs (**[[parameter|parameters]]**), it does the work and gives back one result. The type of the result is the **[[return type]]**.',
 analogy:'A juice machine: put in fruit (arguments), press the button (call), get juice (return value).',
 viz:{type:'func',name:'add',params:['a','b'],args:[3,4],def:'fun add(a: Int, b: Int): Int {\n    return a + b\n}',calc:(a,b)=>a+b,expr:(a,b)=>a+' + '+b+' = '+(a+b)},
 points:['`fun` = “here comes a function”, then its name and `(inputs)`','`: Int` after the brackets = it gives back an Int','`return` sends the result back to the caller'],
 takeaway:'`add(3, 4)` gives back 7. Write once, call many times.',
 notes:'Say: Change the numbers in the machine and replay.\nStudents may ask: “What is the difference between parameter and argument?” — parameter = the name in the definition (a); argument = the real value in the call (3).\nWatch for: calling a function without brackets: `add` vs `add(3, 4)`.\nShort on time: keep.'},
{kind:'code',title:'Functions in Kotlin: shortcuts',text:'Short functions can use `=` (an expression body). Parameters can have a **[[default argument]]**, calls can use a **[[named argument]]**, and a function that returns nothing useful has the type **[[Unit]]**.',
 code:'fun add(a: Int, b: Int): Int {\n    return a + b\n}\n\nfun square(x: Int) = x * x                  // expression body\n\nfun greet(name: String, course: String = "MAD"): Unit {\n    println("Hello $name, welcome to $course")\n}\n\nfun main() {\n    println(add(3, 4))\n    println(square(6))\n    greet("Bilal")                          // uses the default\n    greet(course = "Kotlin", name = "Sana") // named arguments\n}',
 lines:[['1-3','The full form: parameters, return type, body with `return`.'],[5,'One-line form with `=`. Kotlin infers the return type Int.'],[7,'`course` has a default value "MAD". `: Unit` means “returns nothing useful” — usually left out.'],[12,'Call add with the [[argument|arguments]] 3 and 4 → 7.'],[14,'Only the name is given, so course = "MAD".'],[15,'With names, the order does not matter.']],
 output:'7\n36\nHello Bilal, welcome to MAD\nHello Sana, welcome to Kotlin',
 change:'Call `greet("Ali", "Android")`. What prints?',
 notes:'Say: Default and named arguments are why Kotlin rarely needs many versions of the same function.\nStudents may ask: “Is println a function too?” — yes, a function from Kotlin’s standard library.\nWatch for: mixing up the order without names: greet("Kotlin", "Sana") would greet “Kotlin”.\nShort on time: skip Unit.'},
/* ===== K. collections and lambdas ===== */
{title:'Lists and arrays',text:'A list keeps **many values** under one name. Each item has an **[[index]]** — its position, starting at 0.',
 analogy:'Seats in a classroom row: seat 0, seat 1, seat 2…',
 viz:{type:'array',name:'fruits',kind:'mutableListOf',items:['Apple','Mango','Banana'],ops:[{t:'get',i:1},{t:'set',i:2,v:'Grapes'},{t:'add',v:'Orange'},{t:'size'},{t:'each'}]},
 takeaway:'First item = index 0. Last item = size − 1.',
 notes:'Say: Step through: read index 1, replace index 2, add an item, check the size, loop over each.\nStudents may ask: “Why start at 0?” — the index is the distance from the start: the first item is 0 steps away.\nWatch for: asking for index 3 in a list of 3 items → crash (IndexOutOfBoundsException).\nShort on time: keep.'},
{kind:'code',title:'List, MutableList, Set, Map and Array',text:'Kotlin has five everyday collections: **[[List]]** (read-only), **[[MutableList]]** (changeable), **[[Set]]** (no repeats), **[[Map]]** (key → value) and **[[Array]]** (fixed size).',
 code:'fun main() {\n    val days = listOf("Mon", "Tue", "Wed")       // read-only List\n    val cart = mutableListOf("Pen")               // MutableList\n    cart.add("Book")\n    val ids = setOf(3, 1, 3, 2)                   // Set: no duplicates\n    val marks = mapOf("Ali" to 85, "Sara" to 92)  // Map: key to value\n    val seats = arrayOf(10, 20, 30)               // Array: fixed size\n    seats[0] = 15                                 // items can change\n    println(days[0])\n    println(cart)\n    println(ids)\n    println(seats.joinToString())\n    for ((name, score) in marks) println("$name: $score")\n}',
 lines:[[2,'`listOf` = read-only: there is no `add`.'],['3-4','`mutableListOf` lets you add and remove.'],[5,'A Set keeps each value only once: 3, 1, 2.'],[6,'`"Ali" to 85` makes one key → value pair.'],['7-8','`arrayOf` has a fixed size, but `seats[0] = 15` can replace an item.'],[9,'`days[0]` = the first item.'],[12,'[[joinToString]] prints the items as “15, 20, 30”. (Printing an Array directly shows a memory code instead.)'],[13,'`for ((name, score) in marks)` takes each pair apart into two variables.']],
 output:'Mon\n[Pen, Book]\n[3, 1, 2]\n15, 20, 30\nAli: 85\nSara: 92',
 notes:'Say: Real life: List = the class register (read only), MutableList = a shopping list, Set = stamps in a passport (no repeats), Map = a dictionary, Array = an egg tray (fixed slots).\nStudents may ask: “Which one should I use?” — List by default; MutableList when items change; Map for look-ups by name.\nWatch for: trying cart.add on a listOf list — compile error.\nShort on time: skip Set and Array lines.'},
{kind:'code',title:'Lambdas: functions without a name',text:'A **[[lambda]]** is a tiny function written in `{ }`. Inputs go before `->`, the result after it. With exactly one input you can skip the name and say **[[it]]**.',
 analogy:'A sticky note with instructions you hand to someone: “check if the mark is 50 or more”. It has no name; you just pass it on.',
 code:'fun main() {\n    val square = { x: Int -> x * x }          // a lambda stored in a val\n    println(square(5))\n    val isPass: (Int) -> Boolean = { it >= 50 } // one input, so we can say it\n    println(isPass(72))\n    val marks = listOf(45, 72, 90)\n    println(marks.filter { it >= 50 })\n    println(marks.count { it >= 50 })\n}',
 lines:[[2,'Input `x: Int`, arrow `->`, result `x * x`. We keep the lambda in a val called square.'],[3,'Call it like a function: 5 × 5 = 25.'],[4,'`(Int) -> Boolean` is a [[function type]]: takes an Int, gives a Boolean. One input → use `it`.'],[5,'72 >= 50 → true.'],[7,'`filter` runs the lambda for each mark and keeps the ones that give true: [72, 90].'],[8,'`count` counts how many give true: 2.']],
 output:'25\ntrue\n[72, 90]\n2',
 notes:'Say: Lambdas are everywhere in Android: `button.setOnClickListener { … }` is a lambda you hand to the button.\nStudents may ask: “Where did `it` come from?” — Kotlin creates it automatically when the lambda has exactly one input.\nWatch for: using it when there are two inputs — not allowed; name them.\nShort on time: keep lines 2–3 and 7.'},
{title:'filter → map → sum conveyor',text:'Collections have built-in tools that take a lambda. Watch each number ride the belt: **filter** keeps, **map** changes, **sum** adds.',
 points:['`filter { it > 20 }` keeps items where the lambda gives true','`map { it * 2 }` turns each item into a new one','`sum()` adds them all up'],
 viz:{type:'conveyor',name:'numbers',items:[10,20,30,40],f:'filter { it > 20 }',m:'map { it * 2 }',keep:x=>x>20,map:x=>x*2,speed:1500},
 takeaway:'`listOf(10, 20, 30, 40).filter { it > 20 }.map { it * 2 }.sum()` = **140** (verified).',
 notes:'Say: Press Play and narrate: 10 rides in — filter asks “bigger than 20?” — no, dropped. 30 — yes, kept. Then map doubles 30 → 60 and 40 → 80. sum = 140.\nVerified output of the separate steps: [30, 40], then [60, 80], then 140.\nStudents may ask: “Does filter change the original list?” — No. It makes a NEW list; numbers stays [10, 20, 30, 40].\nShort on time: keep; it is the base for lists in Android.'},
/* ===== L. classes ===== */
{kind:'code',title:'Classes and objects',text:'A **[[class]]** is a blueprint. An **[[object]]** is a real thing built from it, with its own data. A class has **[[property|properties]]** (data) and **[[member function|member functions]]** (actions).',
 analogy:'Class = the house plan on paper. Objects = real houses on the street, each with its own family.',
 code:'class Student {\n    var name = ""                    // property (data member)\n    var rollNo = 0\n    fun introduce() {                // member function (method)\n        println("Hi, I am $name, roll no $rollNo")\n    }\n}\n\nfun main() {\n    val s1 = Student()               // object 1\n    s1.name = "Ali"\n    s1.rollNo = 7\n    val s2 = Student()               // object 2\n    s2.name = "Sara"\n    s2.rollNo = 12\n    s1.introduce()\n    s2.introduce()\n}',
 lines:[[1,'`class Student` = the blueprint. Class names start with a capital letter.'],['2-3','Two properties (data members) with starting values.'],['4-6','A member function: it uses the object’s own name and rollNo.'],[10,'`Student()` builds an object. Kotlin has no `new` keyword.'],['11-12','Fill in object 1’s data with a dot: `s1.name`.'],['13-15','Object 2 has its OWN copy of name and rollNo.'],['16-17','Same function, different data → different output.']],
 output:'Hi, I am Ali, roll no 7\nHi, I am Sara, roll no 12',
 notes:'Say: Draw one plan on the board and two houses. Same plan, different families.\nStudents may ask: “Is the class itself an object?” — no, the class is only the plan; objects are built with Student().\nWatch for: lower-case class names; the convention is Capital.\nShort on time: keep.'},
{kind:'code',title:'Constructors: build an object in one line',text:'A **[[constructor]]** fills in an object’s first values. The **[[primary constructor]]** sits in the class header. The **[[init block]]** runs every time an object is created.',
 code:'class Student(val name: String, var marks: Int = 0) {   // primary constructor\n    init {\n        println("Created $name")\n    }\n    fun addMarks(m: Int) {\n        marks += m\n    }\n}\n\nfun main() {\n    val s1 = Student("Hina")\n    val s2 = Student("Bilal", 50)\n    s1.addMarks(40)\n    println("${s1.name}: ${s1.marks}")\n    println("${s2.name}: ${s2.marks}")\n}',
 lines:[[1,'`val name` and `var marks` in the header become properties straight away. `= 0` is a default value.'],['2-4','`init` runs automatically for every new Student.'],['5-7','A member function that adds to this object’s marks.'],[11,'Only the name is given, so marks = 0. “Created Hina” prints.'],[12,'Both values given. “Created Bilal” prints.'],[13,'Hina’s marks: 0 + 40 = 40.']],
 output:'Created Hina\nCreated Bilal\nHina: 40\nBilal: 50',
 notes:'Say: Compare with the previous slide: the primary constructor replaces three lines of “s1.name = …”.\nStudents may ask: “What if I forget val/var in the header?” — then name is only a parameter for init, not a property, and s1.name fails.\nShort on time: keep.'},
{kind:'code',title:'Secondary constructors (your Employee example)',text:'A **[[secondary constructor]]** is an extra `constructor(...)` inside the class. Two constructors with different inputs = constructor **[[overloading]]**. In Kotlin, one primary constructor with a default value usually does the same job.',
 code:'class Employee {                     // no primary constructor\n    var name: String\n    var salary: Double\n    constructor(name: String) {      // secondary constructor 1\n        this.name = name\n        this.salary = 0.0\n    }\n    constructor(name: String, salary: Double) {   // secondary constructor 2\n        this.name = name\n        this.salary = salary\n    }\n}\n\nclass Employee2(var name: String, var salary: Double = 0.0)   // the Kotlin way\n\nfun main() {\n    val e1 = Employee("Ali")\n    val e2 = Employee("Sara", 50000.0)\n    println("${e1.name} ${e1.salary} | ${e2.name} ${e2.salary}")\n    val k1 = Employee2("Ali")\n    val k2 = Employee2("Sara", 50000.0)\n    println("${k1.name} ${k1.salary} | ${k2.name} ${k2.salary}")\n}',
 lines:[['4-7','Constructor 1 takes only a name and sets salary to 0.0. [[this]].name means “this object’s name”.'],['8-11','Constructor 2 takes both values.'],[14,'The Kotlin way: ONE line, with a default salary. It gives exactly the same results.'],['17-19','Your original Employee, now with a print so we can see it works.'],['20-22','Employee2 behaves the same.']],
 output:'Ali 0.0 | Sara 50000.0\nAli 0.0 | Sara 50000.0',
 notes:'Say: Students will see secondary constructors in older code and some Android classes, so they should read them — but write the one-line version.\nCorrection to the original slide: it listed “Delegation to primary constructor” as a use case, but this Employee has no primary constructor. Delegation `: this(...)` is only needed when a primary constructor exists.\nShort on time: show only line 14 and the output.'},
{tag:'Encapsulation',title:'BankAccount: protect your data',text:'**[[encapsulation|Encapsulation]]** means only the object itself may change its own data. **[[private set]]** lets everyone READ the balance but only the class can WRITE it.',
 viz:{type:'tracer',speed:1700,code:BANK,steps:[
  {l:16,n:'The program starts at `main()`.'},
  {l:17,v:{'acc.balance':'1000.0'},n:'A new account is built. The constructor sets balance = 1000.0.'},
  {l:18,n:'Call `deposit(500.0)`.'},{l:4,v:{amount:'500.0'},n:'Inside deposit: amount = 500.0.'},{l:5,v:{'acc.balance':'1500.0'},n:'500.0 > 0, so balance becomes 1500.0.'},
  {l:19,v:{amount:null},n:'Call `withdraw(200.0)`.'},{l:7,v:{amount:'200.0'},n:'Inside withdraw: amount = 200.0.'},{l:8,n:'Is 200.0 <= 1500.0? **true**.'},{l:9,v:{'acc.balance':'1300.0'},n:'balance = 1500.0 − 200.0 = 1300.0.'},{l:10,n:'Return true: success.'},
  {l:20,v:{amount:null},n:'Call `withdraw(5000.0)`.'},{l:7,v:{amount:'5000.0'},n:'Inside withdraw: amount = 5000.0.'},{l:8,n:'Is 5000.0 <= 1300.0? **false**. Skip the block.'},
  {l:12,o:'Rejected: only 1300.0 available',n:'The overdraw is rejected. The balance is safe.'},{l:13,n:'Return false.'},
  {l:21,v:{amount:null},o:'Balance: 1300.0',n:'Print the final balance.'},{l:22,n:'Done. Writing `acc.balance = 1_000_000.0` in main would not compile: *cannot access \'balance\': it is private in \'BankAccount\'*.'}]},
 takeaway:'Public read, private write. In your original slide `var balance` was public, so anyone could set it to any number.',
 notes:'Say: Play it and stop on line 8 for the 5000 withdrawal. Ask: should the bank allow this? The class itself protects the rule.\nVerified with the compiler: output “Rejected: only 1300.0 available” then “Balance: 1300.0”; and the private-set error message shown in the last step.\nStudents may ask: “Why not just make balance private?” — then the app could not even show the balance. private set gives read-only access from outside.\nWatch for: Doubles print with .0 (1300.0), not 1300.\nShort on time: keep; play at 2× speed.'},
{kind:'code',title:'data class: classes that hold data',text:'Put **[[data class|data]]** before `class` and Kotlin writes three helpers for you: **[[toString]]** (readable printing), equals (`==` compares the data) and **[[copy]]**.',
 code:'data class Student(val name: String, val marks: Int)\n\nfun main() {\n    val a = Student("Ali", 85)\n    val b = Student("Ali", 85)\n    val c = a.copy(marks = 90)\n    println(a)\n    println(a == b)\n    println(c)\n}',
 lines:[[1,'One line: a class with two properties and free helper functions.'],['4-5','Two separate objects with the same data.'],[6,'`copy` makes a new object and changes only what you name.'],[7,'Printing uses the automatic toString.'],[8,'`==` compares the DATA, so this is true. (For a normal class it would be false.)'],[9,'The copy with marks = 90.']],
 output:'Student(name=Ali, marks=85)\ntrue\nStudent(name=Ali, marks=90)',
 notes:'Say: In Android, each row of a list on screen (a student, a product, a message) is usually a data class.\nStudents may ask: “Why are the properties val?” — data should not change by accident; copy() makes a changed version safely.\nWatch for: printing a normal (non-data) class gives a code like Student@1b6d3586.\nShort on time: keep the code, skip copy.'},
{kind:'code',title:'Inheritance and polymorphism',text:'With **[[inheritance]]** a child class gets everything from a parent class and can change some of it. Mark the parent and the changeable function **[[open]]**; the child uses **[[override]]**. Same call, different result = **[[polymorphism]]**.',
 analogy:'All vehicles can move(); a car drives on the road, a boat sails on water. One instruction, the right behaviour for each.',
 code:'open class Animal(val name: String) {\n    open fun sound() = "..."\n    fun intro() = "$name says ${sound()}"\n}\n\nclass Dog(name: String) : Animal(name) {\n    override fun sound() = "Woof"\n}\n\nclass Cat(name: String) : Animal(name) {\n    override fun sound() = "Meow"\n}\n\nfun main() {\n    val pets: List<Animal> = listOf(Dog("Tommy"), Cat("Kitty"))\n    for (p in pets) println(p.intro())\n}',
 lines:[[1,'`open` = other classes may inherit from Animal. (Kotlin classes are closed by default.)'],[2,'`open fun` = children may replace this function.'],[3,'intro() is written once in the parent and used by every child.'],[6,'`: Animal(name)` = Dog inherits from Animal and passes the name up to it.'],[7,'`override` = Dog’s own version of sound().'],[15,'`List<Animal>` can hold Dogs and Cats, because both ARE Animals.'],[16,'The same call `p.intro()` gives a different sound for each animal.']],
 output:'Tommy says Woof\nKitty says Meow',
 notes:'Say: Every Android screen uses inheritance: `class MainActivity : AppCompatActivity()` inherits hundreds of ready-made functions.\nStudents may ask: “Why is everything closed by default?” — to stop accidental changes; you open only what you plan to change.\nWatch for: forgetting `open` on the parent → compile error “This type is final”.\nShort on time: keep lines 1, 6, 7 and the output.'},
{kind:'code',title:'object and companion object',text:'An **[[object declaration]]** (`object AppSettings`) creates exactly ONE object for the whole app. A **[[companion object]]** holds things that belong to the class itself, shared by all its objects.',
 analogy:'object = the one principal of the school. companion object = the school’s notice board: one board, shared by every student.',
 code:'object AppSettings {                 // only ONE copy in the whole app\n    var theme = "Light"\n}\n\nclass Student(val name: String) {\n    companion object {               // belongs to the class itself\n        var count = 0\n        fun create(name: String): Student {\n            count++\n            return Student(name)\n        }\n    }\n}\n\nfun main() {\n    AppSettings.theme = "Dark"\n    println(AppSettings.theme)\n    Student.create("Ali")\n    Student.create("Sara")\n    println("Students created: ${Student.count}")\n}',
 lines:[['1-3','No constructor call needed: `AppSettings` already exists, once.'],['6-12','The companion’s `count` is shared: one counter for ALL students.'],[16,'Use the single object by its name.'],['18-19','Call the companion through the class name: `Student.create(...)`.'],[20,'Two students were created, so count = 2.']],
 output:'Dark\nStudents created: 2',
 notes:'Say: You will meet companion objects in Android for constants, e.g. `companion object { const val KEY_NAME = "name" }` used with Intents.\nStudents may ask: “Is companion like static in Java?” — yes, that is the closest idea.\nShort on time: skip; mention it exists.'},
/* ===== M. bridge to Android ===== */
{kind:'code',tag:'Bridge to Android · 1 of 2',title:'The screen: an XML layout',text:'On Android a screen’s look is written in an **[[XML layout]]** file. Each tag is a **[[View]]**: something you see. Attributes (`android:…`) set its size, text and name.',
 lang:'xml',file:'res/layout/activity_main.xml',
 code:'<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"\n    android:layout_width="match_parent"\n    android:layout_height="match_parent"\n    android:orientation="vertical"\n    android:padding="16dp">\n\n    <TextView\n        android:id="@+id/tvGreeting"\n        android:layout_width="wrap_content"\n        android:layout_height="wrap_content"\n        android:textSize="20sp" />\n\n    <Button\n        android:id="@+id/btnSave"\n        android:layout_width="wrap_content"\n        android:layout_height="wrap_content"\n        android:text="Save" />\n</LinearLayout>',
 lines:[[1,'A **[[LinearLayout]]** places its children one after another. The `xmlns:android` line lets us use `android:` attributes.'],['2-3','[[match_parent]]: fill the whole screen width and height.'],[4,'`vertical` = children go top to bottom, in a column.'],[5,'[[padding]] 16 [[dp]]: empty space inside the edges.'],['7-11','A **[[TextView]]** shows text. [[wrap_content]] = just big enough. Text size uses [[sp]].'],[8,'[[android:id]] gives it the name tvGreeting so Kotlin can find it.'],['13-17','A **[[Button]]** with the label “Save” and the id btnSave.'],[18,'The closing tag ends the LinearLayout.']],
 notes:'Say: Do not worry about memorising attributes; Lecture 4 covers layouts in depth. Today just notice: tags = views, ids = names for Kotlin.\nThis XML was checked: well-formed, and the two ids match the Kotlin on the next slide.\nStudents may ask: “What is the + in @+id?” — it creates a new id; without + you refer to an existing one.\nShort on time: lines 7–8 and 13–14 only.'},
{kind:'code',tag:'Bridge to Android · 2 of 2',title:'The behaviour: Kotlin with ViewBinding',text:'An **[[Activity]]** is the Kotlin code behind one screen. With **[[ViewBinding]]** each view that has an id becomes a field, so no **[[findViewById]]** is needed. Everything from today appears here.',
 lang:'kotlin',file:'MainActivity.kt',run:'android',
 code:'data class Student(val name: String, val marks: Int)\n\nclass MainActivity : AppCompatActivity() {\n    private lateinit var binding: ActivityMainBinding\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        binding = ActivityMainBinding.inflate(layoutInflater)\n        setContentView(binding.root)\n\n        // getStringExtra may return null → give a default\n        val name = intent.getStringExtra("name") ?: "Guest"\n        binding.tvGreeting.text = "Hello, $name"\n\n        // old way: findViewById<Button>(R.id.btnSave)\n        binding.btnSave.setOnClickListener {\n            val s = Student(name, 0)\n            binding.tvGreeting.text = "Saved ${s.name}"\n        }\n    }\n}',
 lines:[[1,'A **data class** for one student.'],[3,'**Inheritance**: our screen inherits from [[AppCompatActivity]].'],[4,'[[lateinit]] var: “I will fill this in onCreate”. ActivityMainBinding was generated from activity_main.xml.'],[6,'**override** [[onCreate]]: Android calls it when the screen starts. [[Bundle]]`?` is **nullable**.'],[7,'`super.onCreate` lets the parent class do its own setup first.'],[8,'[[inflate]] the XML into real views.'],[9,'[[setContentView]]: show them on the screen.'],[12,'[[getStringExtra]] returns `String?` (maybe missing), so the **Elvis operator** gives "Guest". The [[Intent]] carries data between screens.'],[13,'`binding.tvGreeting` = the TextView with id tvGreeting. A **string template** sets its text.'],[15,'The older way, for comparison: findViewById.'],['16-19','[[setOnClickListener]] takes a **lambda** that runs on every tap.']],
 takeaway:'val, `?:`, a string template, a lambda, a data class, inheritance and override — all on one Android screen.',
 notes:'Say: Step through slowly; point at each Kotlin idea from today. ViewBinding needs `buildFeatures { viewBinding = true }` in build.gradle.kts (Lecture 3).\nThis Kotlin was type-checked with the real compiler against stand-in Android classes; it needs a real Android project to run.\nStudents may ask: “Where does ActivityMainBinding come from?” — Android Studio generates it from the file name activity_main.xml.\nWatch for: trying to run this in Kotlin Playground — it only runs in an Android project.\nShort on time: lines 12, 13 and 16–19 only.'},
/* ===== practice ===== */
{kind:'mistake',title:'Two classic beginner mistakes',text:'Both compile — and both give the wrong result or crash at run time.',
 left:{code:'val avg = 7 / 2           // 3  (decimal lost!)\nval len = name!!.length   // crashes if name is null',lang:'kotlin'},
 right:{code:'val avg = 7 / 2.0         // 3.5\nval len = name?.length ?: 0   // 0 if name is null',lang:'kotlin'},
 takeaway:'Use a Double for decimals. Use `?.` and `?:` instead of `!!`.',
 notes:'Say: Ask students to explain why each left line is wrong before revealing the right side.\nBoth behaviours were checked with the compiler: 7 / 2 = 3, 7 / 2.0 = 3.5, and !! on null throws NullPointerException.\nShort on time: keep.'},
{kind:'try',title:'Try it yourself',text:'Write each program in Android Studio (or Kotlin Playground). Use the hint if you are stuck, then compare with the answer.',
 items:[
  {title:'FizzBuzz 1–15',task:'Print 1 to 15, but “Fizz” for multiples of 3, “Buzz” for multiples of 5 and “FizzBuzz” for both.',hint:'Loop `for (i in 1..15)`. Inside a `when` with no value, check `i % 15 == 0` FIRST.',
   answer:'fun main() {\n    for (i in 1..15) {\n        val text = when {\n            i % 15 == 0 -> "FizzBuzz"\n            i % 3 == 0 -> "Fizz"\n            i % 5 == 0 -> "Buzz"\n            else -> i.toString()\n        }\n        print("$text ")\n    }\n    println()\n}',output:'1 2 Fizz 4 Buzz Fizz 7 8 Fizz Buzz 11 Fizz 13 14 FizzBuzz'},
  {title:'Temperature converter',task:'Write `fun cToF(c: Double): Double` (F = C × 9 / 5 + 32) and print the result for 37.0 and 100.0.',hint:'Use the one-line form: `fun cToF(c: Double) = c * 9 / 5 + 32`. Pass Doubles (37.0) so nothing is cut off.',
   answer:'fun cToF(c: Double) = c * 9 / 5 + 32\n\nfun main() {\n    println(cToF(37.0))\n    println(cToF(100.0))\n}',output:'98.6\n212.0'},
  {title:'BMI function',task:'BMI (Body Mass Index) is a health number: weight ÷ height². Write `fun bmi(kg: Double, m: Double): Double` = kg ÷ (m × m). Print the BMI for 70 kg and 1.75 m with one decimal place.',hint:'`String.format("%.1f", value)` turns a Double into text rounded to 1 decimal place (`%.1f` = “one digit after the point”).',
   answer:'fun bmi(kg: Double, m: Double): Double = kg / (m * m)\n\nfun main() {\n    println(String.format("%.1f", bmi(70.0, 1.75)))\n}',output:'22.9'}],
 notes:'Say: Give 8–10 minutes. Most bugs will be the order of conditions in FizzBuzz and Int division in the converter.\nAll three answers were compiled and run; the outputs shown are real. Without formatting, bmi(70.0, 1.75) prints 22.857142857142858.\nStudents may ask: “Why 37.0 and not 37?” — the function expects a Double; Kotlin does not change an Int into a Double automatically.\nShort on time: FizzBuzz in class, the other two as homework.'},
{kind:'quiz',tag:'Predict the output',q:'What does this print?  `val a = 7; val b = 2; println(a / b)`',o:['3.5','3','4','Error'],a:1,e:'Both are Int, so the decimal part is dropped: 7 / 2 = 3. Use 7 / 2.0 for 3.5. (Verified with the compiler.)',
 notes:'Say: Let everyone vote with fingers (1–4) before revealing.\nStudents may ask: “Does it round 3.5 up to 4?” — no, Int division simply cuts the decimal part.\nShort on time: keep.'},
{kind:'quiz',q:'`var name: String? = null` — what does `println(name?.length ?: 0)` print?',o:['null','0','It crashes','It does not compile'],a:1,e:'`name?.length` gives null (no crash), then `?:` replaces null with 0. (Verified.)',
 notes:'Say: This pattern — ?. then ?: — is the one they will use most in Android.\nStudents may ask: “What if we used !! here?” — it would crash with NullPointerException.\nShort on time: keep.'},
{kind:'quiz',q:'Which numbers does `for (i in 10 downTo 1 step 3)` visit?',o:['10 7 4 1','10 7 4','1 4 7 10','10 8 6 4 2'],a:0,e:'Start at 10 and go down by 3 while the value is ≥ 1: 10, 7, 4, 1. (Verified.)',
 notes:'Say: Let them check the answer with the Ranges explorer slide.\nWatch for: stopping at 4 because they think 1 is excluded. downTo includes the end.\nShort on time: skip.'},
{kind:'summary',title:'Recap: Lecture 2 in ten lines',points:['Android: 2003 start-up → Google → 2008 first phone → Android 17 (API 37) today','minSdk = oldest phone you support; targetSdk and compileSdk = newest','`fun main()`, `println`, comments `//` and string templates `$x`, `${expr}`','val = set once, var = can change; Kotlin infers types; Int ÷ Int drops decimals','`String?` may be null → use `?.`, `?:`, `let`; avoid `!!`','Operators; if and when give back a value; the first true branch wins','while, do-while, for, break, continue; ranges `..`, until, downTo, step','Functions with defaults and named arguments; lambdas with `it`; filter, map, sum','List, MutableList, Set, Map, Array; classes, constructors, private set, data class','Inheritance (open, override), object and companion object → used on Android screens with XML + ViewBinding'],
 glossary:['API level','SDK','minSdk','targetSdk','compileSdk','Gradle','ART','Dalvik','compiler','console','main()','string template','val','var','type inference','Int','Double','String','Boolean','null','NullPointerException','nullable type','safe call','Elvis operator','let','operator','remainder','expression','when','smart cast','range','function','parameter','argument','Unit','default argument','named argument','lambda','it','List','MutableList','Set','Map','Array','index','class','object','property','member function','constructor','primary constructor','secondary constructor','init block','encapsulation','private set','data class','inheritance','open','override','polymorphism','object declaration','companion object','XML layout','View','LinearLayout','dp','sp','ViewBinding','findViewById','Activity','onCreate','lateinit','setOnClickListener'],
 notes:'Say: Read the ten lines; students tick the objectives in their heads. Tap any glossary word to revise it — the same words are in the portal Glossary and Flashcards.\nAsk the class: which line was the hardest? Revisit that slide with the overview (O).\nShort on time: keep; mark the lecture complete.'}
]});
})();
